typedef struct { void (*write)(void *ctx, const char *msg); void *ctx; } log_t;
typedef struct { const log_t *log; } worker_t;
static void worker_init(worker_t *w, const log_t *log) { w->log = log; }
static void worker_run(const worker_t *w, const char *m) { w->log->write(w->log->ctx, m); }

int main(void) {
    log_t uart_log = { uart_write, &uart0 };   /* composition root */
    worker_t w;
    worker_init(&w, &uart_log);                /* dependency handed in */
    worker_run(&w, "boot");
    return 0;
}
